from uuid import UUID
from datetime import datetime
from pydantic import BaseModel, ConfigDict

class PingLogCreate(BaseModel):
    """Payload generated by the background worker after executing a health check."""
    site_id: UUID
    is_up: bool
    response_time: int | None = None
    status_code: int | None = None
    error_message: str | None = None

class PingLogShow(PingLogCreate):
    """Historical telemetry data returned to the frontend for charting and visualization."""
    id: UUID
    created_at: datetime 

    model_config = ConfigDict(from_attributes=True)